import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"10、【履】 兌下乾上","description":"周易尚氏學 - 10、【履】 兌下乾上","frontmatter":{"title":"10、【履】 兌下乾上","description":"周易尚氏學 - 10、【履】 兌下乾上"},"headers":[],"relativePath":"classics/shangshi/015.md","filePath":"classics/shangshi/015.md"}'),s={name:"classics/shangshi/015.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_10、【履】-兌下乾上" tabindex="-1">10、【履】 兌下乾上 <a class="header-anchor" href="#_10、【履】-兌下乾上" aria-label="Permalink to “10、【履】 兌下乾上”">​</a></h1><p>爾雅釋言。履者禮也。故太玄即擬為禮。禮莫大於辯上下。定尊卑。卦上天下澤。尊卑判然。人之行履。莫大於是。故曰履。乾為虎。四虎尾。兌在乾後。故曰履虎尾。履躡也。言三躡乾後也。乾為人。兌口為哸。人在外故不受哸。彖傳曰。柔履剛。言三步乾剛之後也。荀爽謂三履二。祇以下卦為說。豈知卦名。皆合上下卦取義。無取一卦者。且三履二。是柔乘剛。與卦義正相背。非也。</p><p>彖曰。履。柔履剛也。說而應乎乾。是以履虎尾。不哸人。亨。剛中正。履帝位而不疚。光明也。</p><p>說而應乎乾。謂三應上也。五下履巽。男為病宜有疚。疚即病也。然而不疚者。以五履帝位而中正也。互離為日故光明。人知坎為病。不知巽亦為病。故說疚象無有合者。豈知巽為隕落。當然亦為病。易林。巽之鼎雲。病傷不治。以鼎下巽為病。兌之蠱雲。瘡痍多病。以蠱上艮為瘡痍。下巽為病也。由易林推之易。遁九三雲。有疾厲。豐六二雲。往得疑疾。易原以巽為疾病。故易林本之也。(集解。荀注多利貞二字。兌秋乾冬正合。然他本皆無。)</p><p>象曰。上天下澤。履。君子以辨上下。定民志。</p><p>謙坤為民為志。艮止為定。民志之所以不定者。以不知上下也。上天下澤。尊卑顯然。故君子法之。以定民志。周公制禮。是其事也。</p><p>初九。素履。往無咎。</p><p>四無應。二陽。陽遇陽得敵。宜有咎。然而無咎者。以能素位而行也。故曰素履。言屏去浮華。安常蹈素。循分自守也。能如此。故往無咎。</p><h3 id="象曰。素履之往。獨行願也。" tabindex="-1">象曰。素履之往。獨行願也。 <a class="header-anchor" href="#象曰。素履之往。獨行願也。" aria-label="Permalink to “象曰。素履之往。獨行願也。”">​</a></h3><p>得敵無應。故曰獨行。甘於獨行。故無咎也。先儒於同性相違之義知者鮮。故獨行之故。無有詳者。</p><p>九二。履道坦坦。幽人貞吉。</p><p>伏艮為道路。比陰得中。故坦坦。坦坦者寬平也。兌為昧無應。故曰幽人。居中故貞吉。</p><h3 id="象曰。幽人貞吉。中不自亂也。" tabindex="-1">象曰。幽人貞吉。中不自亂也。 <a class="header-anchor" href="#象曰。幽人貞吉。中不自亂也。" aria-label="Permalink to “象曰。幽人貞吉。中不自亂也。”">​</a></h3><p>象多釋貞為正。此以不亂釋貞。明貞有正定二義也。</p><p>六三。眇能視。跛能履。履虎尾。哸人兇。武人為於大君。</p><p>說文。眇。一目小也。兌為小。離目。故曰眇能視。震為履。二三半震。故曰跛能履。眇而視。跛而履。皆力不足而不止之象。故象曰不足以有明不足以與行也。三正在乾虎後故曰履虎尾。彖言不哸。此言哸者。蓋以上下卦言。乾虎在外。兌在後。故不哸。而以爻言。四虎尾。上虎首。三應在上。上必來三。虎首回噬。故三獨受哸而兇也。伏震為武人。乾為大君。三承乾。故曰武人為於大君。言武人忠於大君。陰順陽。代終事。與訟三之從王事同。象釋曰志剛。剛即謂大君。志剛即釋為義也。虞翻謂三失位。變得正成乾。直以武人變為大君。失之。近師俞蔭甫謂此與坤訟六三之或從王事同義。略露曙光。特又以三升乾上釋為字仍誤也。震武之象。國語重耳筮遇貞屯悔豫。皆有震。曰車有震武。武足跡也。震健。故震為武。易林本之。遇震即言武。於是履及巽之武人。象始大明。</p><h3 id="象曰。眇能視。不足以有明也。跛能履。不足以與行也-咥人之兇。位不當也。武人為於大君。志剛也。" tabindex="-1">象曰。眇能視。不足以有明也。跛能履。不足以與行也，咥人之兇。位不當也。武人為於大君。志剛也。 <a class="header-anchor" href="#象曰。眇能視。不足以有明也。跛能履。不足以與行也-咥人之兇。位不當也。武人為於大君。志剛也。" aria-label="Permalink to “象曰。眇能視。不足以有明也。跛能履。不足以與行也，咥人之兇。位不當也。武人為於大君。志剛也。”">​</a></h3><p>三承重陽。故曰志剛。言志在順陽而行。即坤六三訟六三之所謂從王事也。巽為志。</p><p>九四。履虎尾。愬愬終吉。</p><p>子夏傳。愬愬恐懼也。四當乾末。正為虎尾。乾為惕。故為懼。然下孚於三。三陰。陽得陰志行。故終吉。小畜九五雲。有孚。謂孚於四陰。此與同義。又大有上九吉。隨九四有孚。皆以下乘陰而吉。昔賢不究陰陽相孚之理。但云懼則吉者。非也。</p><h3 id="象日。愬愬終吉。志行也。" tabindex="-1">象日。愬愬終吉。志行也。 <a class="header-anchor" href="#象日。愬愬終吉。志行也。" aria-label="Permalink to “象日。愬愬終吉。志行也。”">​</a></h3><p>陽孚陰故曰志行。巽為志。</p><p>九五。夬履。貞厲。</p><p>夬決也。絕也。言五承乘皆陽。上下應予絕也。貞卜問。厲危也。五居互巽之上。龔隕落。故危。否九五雲。其亡其亡。兌九五雲。孚於剝。有厲。亦皆以居巽上。故危也。</p><h3 id="象曰。夬履貞厲。位正當也。" tabindex="-1">象曰。夬履貞厲。位正當也。 <a class="header-anchor" href="#象曰。夬履貞厲。位正當也。" aria-label="Permalink to “象曰。夬履貞厲。位正當也。”">​</a></h3><p>五正當巽上。故貞厲。</p><p>上九。視履考祥。其旋元吉。</p><p>視履謂三。祥。吉凶之朕兆。上處履之終。故可回視已往之行事。而察其善惡之徵祥。三上相上下。上來三。則皆當位。故曰其旋元吉。旋復也。來也。元吉。大吉也。祥荀作詳。祥詳古通。</p><h3 id="象曰。元吉在上。大有慶也。" tabindex="-1">象曰。元吉在上。大有慶也。 <a class="header-anchor" href="#象曰。元吉在上。大有慶也。" aria-label="Permalink to “象曰。元吉在上。大有慶也。”">​</a></h3><p>五陽獨上有應。故大有慶。</p>',30)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
